css:
.tm-pl h3 { margin: 0 0 6px; }
.tm-pl .head { display: flex; justify-content: space-between; margin-bottom: 8px; }
.tm-pl table.lines { width: 100%; border-collapse: collapse; font-size: 11px; }
.tm-pl table.lines th, .tm-pl table.lines td { border: 1px solid #999; padding: 2px 4px; }
.tm-pl table.lines th { background: #eee; }
.tm-pl td.num, .tm-pl th.num { text-align: right; }
.tm-pl tfoot td { font-weight: 700; }
